Here's a simple Node.js script you can drop into a file called 'deny-access.js':

```javascript
const { spawn } = require('child_process');

async function denyAccess() {
  try {
    const cmd = spawn('firefox', ['--no-remote']);
    const { stdout } = await cmd;
    const text = stdout.toString();
    const [, code] = text.toLowerCase().split('\n');
    // Handle common errors
    if (code == 'access denied') return 'Access denied';
    throw new Error(`${code}`);
  } catch (e) {
    console.log('Error:', e.message);
  }
}

denyAccess();
```

If you want more robust error handling, you can wrap it in try-catch, but `spawn` alone works well. Note that this is just a demo — don't run this against anything critical.
